export function prismaErrorHandler(err,_req,res,_next){
  if(err.code==='P2002')return res.status(409).json({error:'A record with those unique details already exists.'});
  if(err.code==='P2025')return res.status(404).json({error:'The requested record was not found.'});
  if(err.code==='P2003')return res.status(400).json({error:'This change conflicts with related records.'});
  const status=Number(err.status)||500;
  if(status===500)console.error(err);
  return res.status(status).json({error:status===500?'Something went wrong. Please try again.':err.message});
}
